pub fn rapid_upgrade(mut self) -> Self {
    self.config_name.to_mut().insert_str(0, "rapid-upgrade-");

    for ((_, field), epoch) in self.fork_epochs_mut().zip(1..) {
        *field = epoch;
    }

    self
}

